/// <summary>
/// vendTable Form Extension class
/// </summary>
[ExtensionOf(Formstr(VendTable))]
final class METVendTableForm_Extension
{  
}

Method.Source:
    /// <summary>
    /// New control method to override form reference
    /// </summary>
    /// <param name = "_formControl">form control</param>
    public void jumpRef(FormControl _formControl)
    {
        Args args = new Args();        
        args.caller(this);

        METVendTable METVendTable  =_formControl.formRun().dataSource(formDataSourceStr(VendTable,METVendTable)).cursor() as METVendTable;

        RecId vendParentRecId = (select VendParentCompany from METVendLegalEntity where METVendLegalEntity.VendLegalEntityID == METVendTable.VendLegalEntityID).VendParentCompany;

        METVendParentCompany METVendParentCompany = METVendParentCompany::findbyRecId(vendParentRecId);

        args.record(METVendParentCompany);
        args.lookupRecord(METVendParentCompany);
        new MenuFunction(menuitemdisplaystr(METVendParentCompanyLegalEntity), MenuItemType::Display).run(args);
    }
